"""Research-only coverage worksheet. Does not query or alter M1 engines/adapters."""
from pathlib import Path
import json,hashlib,argparse
from decimal import Decimal as D
ap=argparse.ArgumentParser();ap.add_argument('--comparison',default='real-review/input/comparison-data.json');ap.add_argument('--reaction',default='reaction-pressure-review/input/reaction-facts.json');ap.add_argument('--decision',default='april-decision-review/user-decision.json');ap.add_argument('--out',default=str(Path(__file__).parent));a=ap.parse_args();out=Path(a.out);out.mkdir(parents=True,exist_ok=True)
cp,rp,dp=map(Path,[a.comparison,a.reaction,a.decision]);cb,rb=cp.read_bytes(),rp.read_bytes()
cs=hashlib.sha256(cb).hexdigest();rs=hashlib.sha256(rb).hexdigest();assert cs=='184bdef0b687ec0ab7bfcaaac2157ff7916fbc1000ef312d81b5efc0c2e73e15';assert rs=='097971c913b52fbf69dbb286c6e2df380ded3c3d166ca6391de5c5bdb4047c48'
p=json.loads(cb);r=json.loads(rb);decision=json.loads(dp.read_text());assert decision['status']=='USER_CONFIRMED_CASE_DO_NOT_REASK' and decision['manual_grouping']['same_own_interval'] and decision['manual_grouping']['distinct_from_old_major_band']
manual=p['manual_case_audit']['previous_manual_box'];assert manual['start']=='2025-04-07' and manual['end']=='2025-06-02' and manual['records']==39
bars=p['bars'];core=p['core'];pivots=core['pivots'];assert len(pivots)==171;by={x['id']:x for x in pivots};recs={x['date']:x for x in r['records']};dates={b['date']:i for i,b in enumerate(bars)}
ix=[i for i,b in enumerate(bars) if manual['start']<=b['date']<=manual['end']];assert len(ix)==39 and ix==list(range(ix[0],ix[-1]+1))
assert len(recs)==len(bars)==1213
for i,b in enumerate(bars):assert recs[b['date']]['original_bar']==b and recs[b['date']]['macd']['original']==p['macd'][i]
def pivot_matches(date):return [x for x in pivots if x['occurred_at']==date or date in x['source_dates']]
def original_refs(ids):
 return [{'label':f'B{i+1}','original_box_id':b['id'],'scale':b['scale'],'start':b['start'],'source_end':b['source_end'],'confirmed_at':b['confirmed_at'],'research_bounds':b['research_bounds'],'source_turn_ids':b['source_turn_ids'],'matching_original_pivot_ids':[j for j in b['source_turn_ids'] if j in ids],'formal_membership':None} for i,b in enumerate(core['boxes']) if any(j in ids for j in b['source_turn_ids'])]
rows=[]
for i in ix:
 b=bars[i];matches=pivot_matches(b['date']);ids={x['id']for x in matches};rows.append({'original_index':i,'original_bar':b,'original_value_known_on':b['date'],'inside_previously_selected_manual_time_window':True,'qualification':'TIME_COVERAGE_ONLY_NOT_EXHAUSTIVE_FORMAL_SOURCE_MEMBERSHIP','original_pivots_including_source_date_aliases':matches,'original_box_references':original_refs(ids),'formal_original_source_membership':None})
pd=sorted({x['original_bar']['date'] for x in rows if x['original_pivots_including_source_date_aliases']});assert pd==['2025-04-08','2025-04-10','2025-04-22','2025-05-13'];assert sum(len(x['original_pivots_including_source_date_aliases'])for x in rows)==8
assert not pivot_matches('2025-04-07') and not pivot_matches('2025-06-02')
outside=bars[dates[manual['end']]+1];assert outside['date']=='2025-06-03' and outside==p['manual_case_audit']['excluded_bar_source'];op=pivot_matches(outside['date']);assert len(op)==1 and op[0]['scale']=='0.03' and op[0]['confirmed_at']=='2025-06-05'
refs=original_refs({x['id'] for row in rows for x in row['original_pivots_including_source_date_aliases']});assert [x['label']for x in refs]==['B43','B44','B79','B80']
lower=min(D(bars[i]['low'])for i in ix);assert lower==D('27.65') and bars[ix[-1]]['low']=='27.65'
for n in [44,80]:assert core['boxes'][n-1]['research_bounds']['low']=='28.45' and core['boxes'][n-1]['start']=='2025-04-08' and core['boxes'][n-1]['source_end']=='2025-05-13'
samples=[]
for label,date,scope in [('A','2025-04-07','ABC_USER_CONFIRMED_OWN_INTERVAL'),('B','2025-04-10','ABC_USER_CONFIRMED_OWN_INTERVAL'),('C','2025-04-22','ABC_USER_CONFIRMED_OWN_INTERVAL'),('local_representative','2025-05-13','PREVIOUS_USER_CONFIRMED_LOCAL_REPRESENTATIVE'),('last_selected_bar','2025-06-02','PREVIOUS_USER_SELECTED_WINDOW_LAST_BAR_NOT_NEW_ENDPOINT_DECISION'),('next_excluded_bar','2025-06-03','PREVIOUS_USER_EXCLUDED_FROM_THIS_INTERVAL')]:
 i=dates[date];samples.append({'label':label,'case_scope':scope,'original_index':i,'original_bar':bars[i],'original_pivots_including_source_date_aliases':pivot_matches(date),'existing_reaction_record':recs[date],'no_retroactive_pivot_qualification':True,'formal_original_source_membership':None})
e={'schema':'m1-manual-time-coverage-vs-pivot-research/1','qualification':'READ_ONLY_CASE_COMPARISON_NOT_FORMAL_GROUPING_OR_RECOGNITION_ACCURACY','source_comparison_sha256':cs,'source_reaction_sha256':rs,'original_core_result_id':core['result_id'],'as_of':p['as_of'],'anchor':p['anchor'],'source_frame_id':p['source_frame_id'],'source_prefix_fingerprint':p['source_prefix_fingerprint'],'price_basis_id':p['price_basis_id'],'source_gaps':p['source_gaps'],'confirmed_manual_case':manual,'ABC_user_decision':decision,'window_rows':rows,'summary':{'original_records':39,'confirmed_pivot_dates':pd,'confirmed_pivot_records_different_scales':8,'records_without_original_pivot_or_alias':35,'qualification':'SOURCE_REPRESENTATION_COVERAGE_NOT_35_MISSED_PIVOTS_OR_ACCURACY','A_is_confirmed_member_of_ABC_but_not_an_original_pivot':True,'last_selected_bar_not_original_pivot':True,'next_excluded_bar_is_later_confirmed_pivot':True,'manual_time_window_observed_low':str(lower),'last_selected_bar_low_minus_original_B44_B80_research_low':str(lower-D('28.45')),'not_formal_manual_price_boundary_or_breakdown':True},'original_box_reference_intersections':refs,'selected_examples':samples,'derivable_requirement':'Preserve raw-bar interval coverage and user case judgments separately from confirmed pivot qualification and original box references; do not require every included bar to be a pivot or extend to the next pivot automatically.','not_a_product_defect':'Original pivot extraction and source-query contract intentionally cover pivots; reaction facts already retain all original bars. No new tool is required to preserve the evidence.','formal_structure_membership':None,'formal_merge':None,'formal_representative':None,'direct_successor_id':None,'primary_pressure_id':None,'historical_selection_time':None,'historical_signal_eligible':False}
(out/'evidence.json').write_text(json.dumps(e,ensure_ascii=False,indent=2)+'\n')
assert hashlib.sha256(cp.read_bytes()).hexdigest()==cs and hashlib.sha256(rp.read_bytes()).hexdigest()==rs
v={'source_comparison_and_reaction_hashes_unchanged':'PASS','all1213_original_bar_MACD_equal':'PASS_NO_RECOMPUTATION','manual39_contiguous_saved_indices':'PASS','all171_pivots_and_source_date_aliases_checked':'PASS','39_rows_four_dates_eight_original_scale_records_35_without_pivot':'PASS_NOT_ACCURACY','A_and_last_bar_absent_from_pivots_and_aliases':'PASS','next_excluded_bar_original_pivot_later_confirmation_preserved':'PASS','four_original_box_references_and_complete_sources_preserved':'PASS_NOT_FORMAL_MEMBERSHIP','manual_time_coverage_does_not_replace_formal_membership':True,'existing_reaction_records_exact_copy':'PASS','product_code_or_strategy_change':'NONE','core_MACD_query_reaction_adapter_CLI_bootstrap_old_tests_ZIP_browser':'NOT_RUN','Android':'NOT_TESTED_NEW_BUILD','PDF_QA':'PENDING'}
(out/'verification.json').write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n');print(json.dumps(e['summary'],ensure_ascii=False))
